      <script>
        (function () {
          var s = document.querySelector('[data-grow]');
          if (!s) return;
          var still = matchMedia('(prefers-reduced-motion: reduce)').matches;
          var count = function () {
            s.querySelectorAll('[data-count]').forEach(function (el) {
              var end = +el.dataset.count, t0 = performance.now(), dur = 1400;
              (function tick(now) {
                var k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
                el.textContent = Math.round(end * e);
                if (k < 1) requestAnimationFrame(tick);
              })(t0);
            });
          };
          if (still || !('IntersectionObserver' in window)) { s.classList.add('is-in'); return; }
          var io = new IntersectionObserver(function (es) {
            if (!es[0].isIntersecting) return;
            s.classList.add('is-in'); count(); io.disconnect();
          }, { threshold: 0.25 });
          io.observe(s);
        })();
      </script>
  
